class Range {
    constructor(from, to, step = 1) {
        this.from = from;
        this.to = to;
        this.step = step;
    }

    [Symbol.iterator]() {
        let current = this.from;
        const { to, step } = this;
        return {
            next() {
                const inside = step > 0 ? current <= to : current >= to;
                if (!inside) return { value: undefined, done: true };
                const value = current;
                current += step;
                return { value, done: false };
            },
        };
    }
}

