class Grid {
    constructor(rows) {
        this.rows = rows;
    }

    [Symbol.iterator]() {
        const rows = this.rows;
        let r = 0;
        let c = 0;
        return {
            next() {
                while (r < rows.length && c >= rows[r].length) {
                    r++;
                    c = 0;
                }
                if (r >= rows.length) return { value: undefined, done: true };
                const cell = { row: r, col: c, value: rows[r][c] };
                c++;
                return { value: cell, done: false };
            },
        };
    }
}

