function chunk(iterable, size) {
    return {
        [Symbol.iterator]() {
            const source = iterable[Symbol.iterator]();
            return {
                next() {
                    const part = [];
                    while (part.length < size) {
                        const step = source.next();
                        if (step.done) break;
                        part.push(step.value);
                    }
                    return part.length > 0 ? { value: part, done: false } : { value: undefined, done: true };
                },
            };
        },
    };
}

