function zip(first, second) {
    return {
        [Symbol.iterator]() {
            const a = first[Symbol.iterator]();
            const b = second[Symbol.iterator]();
            return {
                next() {
                    const x = a.next();
                    const y = b.next();
                    if (x.done || y.done) return { value: undefined, done: true };
                    return { value: [x.value, y.value], done: false };
                },
            };
        },
    };
}

